// ── DOMAIN RULES (spec §6) ────────────────────────────────────────────────────
// How much room a piece takes comes from the product; the length fallback is
// only for material the catalogue does not describe yet.
const slotsPerPiece = (len: number, sku?: string) => {
  const p = sku ? (store as any)?.productSlots?.(sku) : null;
  return p || (len <= 1500 ? 1 : 2);
};
// and how much room there is comes from the workstation
// A batch is made by hand in Job Assignment, so nothing here decides a size.
const furnaceCapacity = (_f: string, _len: number) => 999;
// (a machine's working length is part of its description — see stationSpec)
const BED: any = new Proxy({}, { get: (_t, code: string) => (store as any)?.sizeOf?.(code) || 3000 });
// The three angle grinders share one queue: work assigned to angle grinding can be
// picked up by whichever machine is free. Any of them can also be switched to
// surface-grinding mode and take Surface Grinding 1 / 2 from SG-DLT's queue.
// ── WORKSTATION MASTER (Inventory · Master Data) ─────────────────────────────
// Every station declares the operations it performs, the pool it shares a queue
// with, and the stations it can be switched over to. Job Assignment's filters,
// the shared queues and the machine switching all read this — nothing is coded
// against a particular machine.
const CYCLES = ["EAT", "SWAN", "OVEN"];
const WS_POOLS: Record<string, string[]> = { "AG-POOL": ["AG-ALP", "AG-GMM"] };
// Extra operations a station can perform beyond the ones its own cycle steps
// name. An angle grinder can run surface grinding — but not bunch grinding,
// which needs the 3000 mm bed. Capability is stated as OPERATIONS, not as
// "this machine can stand in for that machine".
// Standard time per piece, in seconds, per operation. This is the master that
// turns raw run durations into performance: actual vs standard, variance, and
// a capacity figure per station. Editable in Inventory · Workstations.
const STD_SEC: Record<string, number> = {
  "Band Saw Cutting": 210, "Punching": 45, "Straightening": 120, "Bunch Grinding": 90,
  "OP10": 260, "OP20": 300, "OP30": 240, "Hardening": 40, "Quenching": 25,
  "Unique Identification": 55, "Straightening - Manual": 100, "Straightening - Final": 95,
  "Tempering 1": 30, "Tempering 2": 30, "Tempering 3": 30, "Stress Relieving": 30,
  "Straightening - Hydraulic": 110, "Surface Grinding 1": 150, "Surface Grinding 2": 140,
  "Inspection": 75, "Hardness Test": 60, "Converting": 180, "Child Punching": 45,
  "Bevel Grinding": 200, "Protection": 55, "Protection - Final": 55, "Packing": 65,
};
// (what a machine can also perform is part of its description — see stationSpec)
const WS_EXTRA_OPS: Record<string, string[]> = new Proxy({}, {
  get: (_t, code: string) => (store as any)?.specOf?.(code)?.extraOps || [],
}) as any;
const poolOf = (code: string) => Object.keys(WS_POOLS).find(p => WS_POOLS[p].includes(code)) || null;
const poolMembers = (code: string) => { const p = poolOf(code); return p ? WS_POOLS[p] : [code]; };
const AG_POOL = WS_POOLS["AG-POOL"];
const inAgPool = (code: string) => !!poolOf(code);
// A station performs its own operations AND every operation of the machines it
// shares a queue with — the pool is one capability, not three separate ones.
const cycleOf = (code: string) => (FBD_WS.some(w => w.code === code) ? FBD_CYCLE : DHA_CYCLE);
const wsOwnOperations = (code: string) => Array.from(new Set(cycleOf(code).filter((s: any) => s.workstation === code).map((s: any) => s.operation)));
// Everything this machine can perform: its own operations, its pool's, plus extras.
const wsOperations = (code: string) => Array.from(new Set([
  ...poolMembers(code).flatMap(c => wsOwnOperations(c)),
  ...poolMembers(code).flatMap(c => WS_EXTRA_OPS[c] || []),
]));
const wsExtraOps = (code: string) => Array.from(new Set(poolMembers(code).flatMap(c => WS_EXTRA_OPS[c] || [])));
// Which station a cycle step names for an operation — where its queue lives.
const opOwner = (op: string) => DHA_CYCLE.find(s => s.operation === op)?.workstation || "";
const opStep = (op: string) => DHA_CYCLE.find(s => s.operation === op)?.step ?? 0;
const BARS_PER_SET = 5;
const surfaceCap = (len: number) => len <= 1500 ? 2 : 1;
// valid workstations (spec §6.3): pools for grinding only; long bars only on AG-GMM
const validWorkstationsFor = (rule: string, ws: string, len: number): string[] => {
  if (rule === "PR-SG") return len > 1500 ? ["SG-DLT", "AG-GMM"].filter(w => w === "AG-GMM" || w === "SG-DLT") : ["SG-DLT", "AG-GMM"];
  if (rule === "PR-BV") return len > 1500 ? ["AG-GMM"] : ["AG-ALP", "AG-GMM"];
  return [ws];
};
// composeSlotRun (spec §6.1): current piece + same-cycle non-HOLD, same size first
function composeSlotRun(job: any, pool: any[], model: string, ws: string) {
  const mates: any[] = [job];
  const cand = pool.filter(j => j.uid !== job.uid && j.cycle_type === job.cycle_type && j.status !== "HOLD")
    .sort((a, b) => (a.bar_length_mm === job.bar_length_mm ? -1 : 0) - (b.bar_length_mm === job.bar_length_mm ? -1 : 0));
  if (model === "bunch") {
    const bed = BED[ws] || 3000;
    for (const c of cand) {
      const bySize: any = {};
      [...mates, c].forEach(m => { bySize[m.bar_length_mm] = (bySize[m.bar_length_mm] || 0) + 1; });
      const setLens = Object.entries(bySize).flatMap(([len, n]: any) => Array(Math.ceil(n / BARS_PER_SET)).fill(Number(len)));
      if (setLens.reduce((a, l) => a + l, 0) <= bed) mates.push(c);
      if (mates.length >= BARS_PER_SET * 2) break;
    }
  } else if (model === "surface") {
    const cap = surfaceCap(job.bar_length_mm);
    for (const c of cand) { if (mates.length >= cap) break; if (c.bar_length_mm === job.bar_length_mm) mates.push(c); }
  } else if (model === "furnace") {
    const cap = furnaceCapacity(ws, job.bar_length_mm);
    for (const c of cand) { if (mates.length >= cap) break; mates.push(c); }
  }
  return mates;
}
// UID issuance: cycle letter + a number from ONE running sequence.
//
// The number does not restart per cycle. It used to, which meant E001, S001 and
// O001 all existed — the same number on three different bars — and a piece
// halfway through the shop could show as "001", reading like something just
// punched. One sequence per plant means a number is a piece, and a UID that
// looks new is new.
const UID_LETTER: any = { EAT: "E", SWAN: "S", OVEN: "N" };   // N, not O: an O reads as a zero
let uidSeq = 0;
const UID_TAKEN = new Set<string>();
const uidTaken = (uid: string) => UID_TAKEN.has(uid);
const claimUid = (uid: string) => { UID_TAKEN.add(uid); return uid; };
const issueUid = (cycle: string): string => {
  let uid = "";
  do { uid = (UID_LETTER[cycle] || "X") + String(++uidSeq).padStart(4, "0"); } while (UID_TAKEN.has(uid));
  UID_TAKEN.add(uid); return uid;
};
const peekUid = (cycle: string) => (UID_LETTER[cycle] || "X") + String(uidSeq + 1).padStart(4, "0");


