// ── Manufacturing Orders (Inventory) ─────────────────────────────────────────
// Creating an order pulls the pieces closest to dispatch and pins them to the
// front of every queue until the order is met.
function InvMO({ role }: any) {
  const st = useJobStore() as any;
  const [cycle, setCycle] = useState("EAT");
  const [design, setDesign] = useState("");
  const [size, setSize] = useState(1424);
  // only what this finished size is declared to come in — an order cannot ask
  // for a design the product is not made to
  const fgProduct = st.catalogueWithStock("dharmapuri").find((p: any) => p.sku === `FG-KNF-${size}`);
  const designOptions: string[] = fgProduct ? st.attrValuesFor(fgProduct, st.attrFor("design")) : [];
  useEffect(() => { setDesign((d: string) => (designOptions.includes(d) ? d : "")); }, [size]);
  const [qty, setQty] = useState("");
  const [due, setDue] = useState("");
  const [openMo, setOpenMo] = useState<string | null>(null);
  const sizes = Array.from(new Set(st.bomFor(cycle).sizes.map((s: any) => s.fg))) as number[];
  useEffect(() => { if (!sizes.includes(size)) setSize(sizes[0]); }, [cycle]);
  const avail = st.moCandidates(cycle, size, design || undefined);
  const editable = can.assign(role);
  const preview = avail.slice(0, Math.max(0, Number(qty) || 0));

  return (
    <>
      <HeaderBand icon="clipboard" kicker={`${st.mos.length} orders · allocation runs from dispatch backwards`} title="Manufacturing Orders" />
      <div style={{ padding: 24, display: "flex", flexDirection: "column", gap: 18 }}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 18, alignItems: "start" }}>
          <Panel title="New order" sub="pieces are allocated the moment it is created">
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
                <div><div style={{ fontSize: 12.5, color: T.t3, marginBottom: 5 }}>Grade · cycle <span style={{ color: T.red }}>*</span></div>
                  <Picker value={cycle} onChange={(e: any) => setCycle(e.target.value)} options={CYCLES} /></div>
                <div><div style={{ fontSize: 12.5, color: T.t3, marginBottom: 5 }}>Design <span style={{ color: T.red }}>*</span></div>
                  <Picker value={design} onChange={(e: any) => setDesign(e.target.value)}
                    options={[["", "— choose —"], ...designOptions.map((d: string) => [d, d])] as any} /></div>
                <div><div style={{ fontSize: 12.5, color: T.t3, marginBottom: 5 }}>Finished size</div>
                  <Picker value={String(size)} onChange={(e: any) => setSize(Number(e.target.value))} options={sizes.map(s => [String(s), s + " mm"])} /></div>
                <div><div style={{ fontSize: 12.5, color: T.t3, marginBottom: 5 }}>Quantity</div>
                  <Field value={qty} onChange={(e: any) => setQty(e.target.value)} placeholder="0" w={110} mono right err={Number(qty) > avail.length} /></div>
                <div><div style={{ fontSize: 12.5, color: T.t3, marginBottom: 5 }}>Due</div>
                  <Field value={due} onChange={(e: any) => setDue(e.target.value)} placeholder="2026-09-30" w={140} mono /></div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
                <Btn disabled={!editable || !Number(qty) || !due || !design} onClick={() => {
                  const res = st.createMO(`${size} · ${cycle} · ${design}`, cycle, size, Number(qty), due, design);
                  if (!res.no) { TOAST(`An order needs a ${res.error} — it names what the floor must make`, "warn"); return; }
                  TOAST(`${res.no} created · ${res.allocated} pieces allocated to the front of the queue`);
                  setQty("");
                }}>Create order</Btn>
                <span style={{ fontFamily: mono, fontSize: 12, color: Number(qty) > avail.length ? T.amber : T.t4 }}>
                  {avail.length} unallocated {size}mm · {cycle}{design ? " · " + design : ""} in the flow
                  {Number(qty) > avail.length ? ` · ${Number(qty) - avail.length} short` : ""}
                </span>
                {!design && <span style={{ fontSize: 12.5, color: T.amber }}>Choose a design — an order must name both the grade and the design.</span>}
              </div>
            </div>
          </Panel>

          <Panel title="What would be allocated" sub="reverse order — nearest dispatch first" pad={false}>
            {preview.length === 0
              ? <div style={{ padding: "16px 18px", fontSize: 13, color: T.t4 }}>Enter a quantity to preview which pieces this order would claim.</div>
              : preview.slice(0, 8).map((j: any, i: number) => (
                <div key={j.uid} style={{ display: "flex", alignItems: "center", gap: 10, height: 42, padding: "0 18px", borderTop: i > 0 ? `1px solid ${T.well}` : "none", fontSize: 13 }}>
                  <span style={{ fontFamily: mono, fontSize: 10, color: T.t4, width: 20 }}>{i + 1}</span>
                  <button onClick={() => OPEN_JOB(j.uid)} style={{ border: "none", background: "transparent", padding: 0, fontFamily: mono, color: T.blue, cursor: "pointer", fontSize: 13 }}>{j.uid}</button>
                  <span style={{ color: T.t2, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{j.step_name}</span>
                  <MonoChip>step {j.current_step}</MonoChip>
                </div>
              ))}
            {preview.length > 8 && <div style={{ padding: "10px 18px", fontFamily: mono, fontSize: 11, color: T.t4, borderTop: `1px solid ${T.well}` }}>+{preview.length - 8} more</div>}
          </Panel>
        </div>

        <DcTable cols={[["Order", 130], ["Item", "1fr"], ["Progress", 200], ["Allocated", 110, "right"], ["Due", 110, "right"], ["Status", 100, "right"], ["", 90, "right"]]} rowH={46}
          rows={st.mos.map((m: any) => {
            const alloc = st.moAllocated(m.no);
            const pct = Math.min(100, Math.round((m.done / m.qty) * 100));
            const short = Math.max(0, m.qty - m.done - alloc);
            return [
              <button key="n" onClick={() => setOpenMo(openMo === m.no ? null : m.no)} style={{ border: "none", background: "transparent", padding: 0, fontFamily: mono, color: T.blue, cursor: "pointer", fontSize: 13, textAlign: "left" }}>{m.no}</button>,
              <span key="i" style={{ display: "inline-flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                <MonoChip>{m.fg_size} mm</MonoChip>
                <MonoChip tone={T.deep}>{m.cycle}</MonoChip>
                {m.design ? <MonoChip tone={T.purple}>{m.design}</MonoChip>
                  : <Tooltip label="This order predates the design requirement — it matches any design"><span style={{ fontSize: 11, color: T.amber }}>any design</span></Tooltip>}
              </span>,
              <span key="p" style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ flex: 1, height: 6, borderRadius: 3, background: T.mutedBg, overflow: "hidden" }}>
                  <span style={{ display: "block", width: pct + "%", height: "100%", background: pct >= 100 ? T.okGrad : T.grad }} /></span>
                <span style={{ fontFamily: mono, fontSize: 12 }}>{m.done}/{m.qty}</span></span>,
              <span key="a" style={{ fontFamily: mono, color: short ? T.amber : T.t2 }}>{alloc}{short ? ` (−${short})` : ""}</span>,
              <span key="d" style={{ fontFamily: mono, fontSize: 12 }}>{m.due}</span>,
              <span key="s" style={{ fontWeight: 600, color: pct >= 100 ? T.green : short ? T.amber : T.t2 }}>{pct >= 100 ? "DONE" : short ? "SHORT" : "COVERED"}</span>,
              editable && pct < 100 ? <span key="x" style={{ display: "inline-flex", gap: 6, justifyContent: "flex-end", width: "100%" }}>
                  <Tooltip label="Pull more pieces into this order as they become available">
                    <Btn tone="secondary" style={{ height: 28, padding: "0 10px", fontSize: 12 }} onClick={() => { const n = st.allocateMO(m.no); TOAST(n ? `${n} more pieces allocated to ${m.no}` : "No unallocated pieces match this order", n ? "ok" : "warn"); }}>Top up</Btn>
                  </Tooltip>
                </span> : "",
            ];
          })}
          footer={<span>Allocated pieces jump to the front of every station queue until the order is met.</span>} />

        {openMo && (() => {
          const jobs = st.flowJobs.filter((j: any) => j.mo === openMo && st.statusOf(j) !== "CLOSED")
            .sort((a: any, b: any) => b.current_step - a.current_step);
          return (
            <Slideover title={openMo} sub={`${jobs.length} pieces allocated`} onClose={() => setOpenMo(null)}>
              <div style={{ padding: "14px 20px", display: "flex", gap: 8, flexWrap: "wrap" }}>
                <Btn tone="secondary" onClick={() => { const n = st.allocateMO(openMo); TOAST(n ? `${n} more allocated` : "Nothing left to allocate", n ? "ok" : "warn"); }}>Top up</Btn>
                {editable && <Btn tone="danger" onClick={() => CONFIRM({ title: `Cancel ${openMo}?`, tone: "danger", confirmLabel: "Cancel order",
                  body: "The order is removed and its pieces lose priority, returning to normal queue order.",
                  onConfirm: () => { st.releaseMO(openMo); setOpenMo(null); TOAST(`${openMo} cancelled`, "warn"); } })}>Cancel order</Btn>}
              </div>
              {jobs.map((j: any, i: number) => (
                <div key={j.uid} style={{ display: "flex", alignItems: "center", gap: 10, minHeight: 44, padding: "4px 20px", borderTop: `1px solid ${T.well}`, fontSize: 13 }}>
                  <button onClick={() => { setOpenMo(null); OPEN_JOB(j.uid); }} style={{ border: "none", background: "transparent", padding: 0, fontFamily: mono, color: T.blue, cursor: "pointer", fontSize: 13 }}>{j.uid}</button>
                  <span style={{ color: T.t3, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{j.step_name}</span>
                  <MonoChip>{j.workstation}</MonoChip>
                </div>
              ))}
              {jobs.length === 0 && <div style={{ padding: "16px 20px", fontSize: 13, color: T.t4 }}>No live pieces allocated — the order may already be met.</div>}
            </Slideover>
          );
        })()}
      </div>
    </>
  );
}
