function LogTransfers({ role, embedded }: any) {
  const store = useJobStore();
  const [item, setItem] = useState(""); const [qty, setQty] = useState(""); const [dir, setDir] = useState("d2f");
  return (
    <>
      {!embedded && <HeaderBand icon="box" kicker="Dharmapuri ⇆ Faridabad stock moves" title="Internal Transfers" />}
      <div style={{ padding: embedded ? 0 : 24, display: "flex", flexDirection: "column", gap: 18, maxWidth: embedded ? "none" : 860 }}>
        {can.assign(role) && (
          <Panel title="New transfer">
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
              <SegSwitch height={34} value={dir} onChange={setDir} options={[["d2f", "DHA → FBD"], ["f2d", "FBD → DHA"]]} />
              <input value={item} onChange={e => setItem(e.target.value)} placeholder="Item" style={{ flex: 1, minWidth: 180, height: 38, padding: "0 12px", borderRadius: 6, border: `1px solid ${T.borderIn}`, background: T.cardBg, fontSize: 13, fontFamily: "inherit", color: T.t1, outline: "none" }} />
              <input value={qty} onChange={e => setQty(e.target.value)} placeholder="Qty" style={{ width: 90, height: 38, padding: "0 12px", borderRadius: 6, border: `1px solid ${T.borderIn}`, background: T.cardBg, fontSize: 13, fontFamily: mono, color: T.t1, outline: "none" }} />
              <Btn disabled={!item || !qty} onClick={() => { store.transferStock(item, Number(qty), dir === "d2f" ? "Dharmapuri" : "Faridabad", dir === "d2f" ? "Faridabad" : "Dharmapuri"); setItem(""); setQty(""); }}>Transfer</Btn>
            </div>
          </Panel>
        )}
        <Panel title="Transfer log" pad={false}>
          {store.transfersLog.length === 0 && <div style={{ padding: 18 }}><EmptyState icon="box" title="No transfers yet" body="Plant-to-plant moves appear here and in Stock Moves." /></div>}
          {store.transfersLog.map((t: any, i: number) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, height: 44, padding: "0 18px", borderTop: i > 0 ? `1px solid ${T.well}` : "none", fontSize: 13 }}>
              <span style={{ fontWeight: 500 }}>{t.item}</span>
              <span style={{ fontFamily: mono, color: T.t3 }}>{t.qty} pcs</span>
              <span style={{ color: T.t3, flex: 1 }}>{t.from} → {t.to}</span>
              <span style={{ fontFamily: mono, fontSize: 11, color: T.t4 }}>{hhmm(t.ts)}</span>
            </div>
          ))}
        </Panel>
      </div>
    </>
  );
}

