function Modal({ title, onClose, children }: any) {
  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(18,22,28,.44)", zIndex: 80, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: "9vh 20px 20px" }}>
      <div onClick={e => e.stopPropagation()} style={{ width: 560, maxWidth: "100%", maxHeight: "78vh", overflow: "auto", background: T.cardBg, border: `1px solid ${T.border}`, borderRadius: 12, boxShadow: "0 40px 90px rgba(0,0,0,.35)", animation: "riseIn .22s cubic-bezier(.2,.8,.2,1) both" }}>
        <div style={{ display: "flex", alignItems: "center", padding: "14px 18px", borderBottom: `1px solid ${T.border}` }}>
          <span style={{ fontSize: 15, fontWeight: 600, color: T.t1 }}>{title}</span>
          <button onClick={onClose} style={{ marginLeft: "auto", border: "none", background: "transparent", cursor: "pointer", color: T.t4, display: "inline-flex" }}><Icon name="close" size={15} /></button>
        </div>
        {children}
      </div>
    </div>
  );
}

let OPEN_BATCH: (bid: string) => void = () => {};
function BatchDetailHost() {
  const store = useJobStore();
  const [bid, setBid] = useState<string | null>(null);
  OPEN_BATCH = setBid;
  if (!bid) return null;
  const run = store.runRegistry.find(r => r.bid === bid);
  const ht = store.htBatches.find(b => b.bid === bid);
  const asgn = store.asgnBatches.find((b: any) => b.bid === bid);
  const jw = store.jobworkOrders.find((o: any) => o.id === bid);
  const uids: string[] = run?.uids || ht?.uids || asgn?.uids || jw?.uids || [];
  const kind = ht ? "Furnace batch" : asgn ? "Assignment batch" : jw ? "Job work" : "Run";
  const meta = ht ? `${ht.furnace} · ${ht.process} · ${ht.cycle} · ${ht.open ? "OPEN" : "CLOSED"}` : run ? `${run.ws} · closed ${new Date(run.ts).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}` : asgn ? `${asgn.ws} · ${asgn.op}` : jw ? `${jw.vendor} · step ${jw.step} · ${jw.open ? "AT VENDOR" : "RETURNED"}` : "";
  return (
    <Modal title={`${kind} · ${bid}`} onClose={() => setBid(null)}>
      <div style={{ padding: 18, display: "flex", flexDirection: "column", gap: 12 }}>
        <span style={{ fontSize: 13, color: T.t3 }}>{meta || "No record found for this id."}</span>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          {uids.map(u => <button key={u} onClick={() => { setBid(null); NAV_TO("uid", { uid: u }); }} style={{ border: `1px solid ${T.border}`, background: T.pageBg, borderRadius: 4, padding: "3px 9px", fontFamily: mono, fontSize: 11, color: T.blue, cursor: "pointer" }}>{u}</button>)}
          {uids.length === 0 && <span style={{ fontSize: 13, color: T.t4 }}>No pieces recorded.</span>}
        </div>
      </div>
    </Modal>
  );
}

function CommandPalette({ onGo, role }: any) {
  const store = useJobStore();
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState("");
  OPEN_PALETTE = () => { setOpen(true); setQ(""); };
  useEffect(() => {
    const h = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") { e.preventDefault(); setOpen(o => !o); setQ(""); }
      if (e.key === "Escape") setOpen(false);
    };
    window.addEventListener("keydown", h); return () => window.removeEventListener("keydown", h);
  }, []);
  if (!open) return null;
  const SCREENS: [string, string, string, string?][] = [
    ["Dashboard", "manufacturing", "command"], ["Production Floor", "manufacturing", "floor"], ["Shopfloor Display", "manufacturing", "shopfloor"],
    ["Command Centre", "manufacturing", "jobassign"], ["My Workstation", "manufacturing", "jobexec"], ["UID Lookup", "manufacturing", "uid"],
    ["HT Batch", "manufacturing", "htbatch"], ["Shift report", "shiftreport", "shiftreport"],
    ["Shift Roster", "workforce", "roster"], ["Today · shift", "workforce", "today"], ["Handover", "workforce", "handover"],
    ["Crews & Teams", "workforce", "crews"], ["Capability", "workforce", "capability"], ["Shift Patterns", "workforce", "patterns"],
    ["Reports", "manufacturing", "reports"], ["Cycle Builder", "manufacturing", "cycle"], ["Page Designer", "manufacturing", "jabuilder"],
    ["Standard Times", "manufacturing", "stdtimes"], ["Storage", "manufacturing", "storage"], ["Sub-cycles", "manufacturing", "cycle"],
    ["Inventory Overview", "inventory", "overview"], ["Products", "inventory", "products"], ["Bill of Materials — conversions", "inventory", "bom"],
    ["Vendors", "inventory", "vendors"], ["Manufacturing Orders", "inventory", "mo"], ["Physical Inventory", "inventory", "adjust"], ["Scrap", "inventory", "scrap"],
    ["Replenishment", "inventory", "replenish"], ["Stock Moves", "inventory", "moves"], ["Product Master", "inventory", "productmaster"],
    ["Workstations", "inventory", "masters"], ["Inventory Configuration", "inventory", "config"], ["Inventory Reporting", "inventory", "reporting"],
    ["Inbound — receiving & intake", "logistics", "inbound"], ["New Movement", "logistics", "movement"], ["All Movements", "logistics", "dispatches"], ["Subcontracting", "logistics", "jobwork"], ["Internal Transfers", "logistics", "transfers"],
    ["Movement Builder", "logistics", "typebuilder"], ["Logistics Settings", "logistics", "settings"], ["Logistics Reporting", "logistics", "logreports"],
    ["Plant Setup", "admin", "plantsetup"], ["Users & Roles", "admin", "users"], ["Invite User", "admin", "invite"], ["Employee Profiles", "admin", "employees"],
    ["Activity Log", "admin", "activity"], ["Admin Settings", "admin", "settings"], ["Import / Export", "admin", "dataio"], ["Backup & Restore", "admin", "database"],
  ];
  const ql = q.trim().toLowerCase();
  const uidHit = ql && store.flowJobs.find(j => j.uid.toLowerCase() === ql);
  const hits = SCREENS.filter(s => !(store as any).pageHidden(role || "Admin", s[1], s[2]))
    .filter(s => !ql || s[0].toLowerCase().includes(ql)).slice(0, 9);
  return (
    <div onClick={() => setOpen(false)} style={{ position: "fixed", inset: 0, background: "rgba(18,22,28,.44)", zIndex: 85, display: "flex", justifyContent: "center", alignItems: "flex-start", padding: "12vh 20px 20px" }}>
      <div onClick={e => e.stopPropagation()} style={{ width: 520, maxWidth: "100%", background: T.cardBg, border: `1px solid ${T.border}`, borderRadius: 12, overflow: "hidden", boxShadow: "0 40px 90px rgba(0,0,0,.4)", animation: "riseIn .2s cubic-bezier(.2,.8,.2,1) both" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "12px 16px", borderBottom: `1px solid ${T.border}` }}>
          <Icon name="search" size={15} color={T.t4} />
          <input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="Go to a screen, or type a UID…"
            style={{ flex: 1, border: "none", outline: "none", background: "transparent", fontSize: 14, fontFamily: "inherit", color: T.t1 }} />
          <span style={{ fontFamily: mono, fontSize: 10, color: T.t4, border: `1px solid ${T.border}`, borderRadius: 3, padding: "1px 5px" }}>esc</span>
        </div>
        <div style={{ padding: 8, maxHeight: 380, overflow: "auto" }}>
          {uidHit && (
            <button onClick={() => { setOpen(false); onGo("manufacturing", "uid", { uid: uidHit.uid }); }} style={{ display: "flex", alignItems: "center", gap: 10, width: "100%", textAlign: "left", height: 40, padding: "0 10px", borderRadius: 7, border: "none", cursor: "pointer", background: T.softBlue, color: T.deep, fontWeight: 600, fontSize: 13, fontFamily: "inherit" }}>
              <Icon name="qr" size={15} color={T.deep} />Open UID {uidHit.uid} · {uidHit.step_name}
            </button>
          )}
          {hits.map(([label, m, s]) => (
            <button key={m + s} onClick={() => { setOpen(false); onGo(m, s); }} className="e21-nav" style={{ display: "flex", alignItems: "center", gap: 10, width: "100%", textAlign: "left", height: 38, padding: "0 10px", borderRadius: 7, border: "none", cursor: "pointer", background: "transparent", color: T.t2, fontSize: 13, fontFamily: "inherit" }}>
              <Icon name="chevronRight" size={13} color={T.t4} />{label}
              <span style={{ marginLeft: "auto", fontFamily: mono, fontSize: 10, letterSpacing: ".08em", textTransform: "uppercase", color: T.t4 }}>{m}</span>
            </button>
          ))}
          {!hits.length && !uidHit && <div style={{ padding: 14, fontSize: 13, color: T.t4 }}>No matches.</div>}
        </div>
      </div>
    </div>
  );
}

function NotifBell() {
  const store = useJobStore();
  const [open, setOpen] = useState(false);
  const items = store.notificationsFor();
  return (
    <div style={{ position: "relative" }}>
      <button onClick={() => setOpen(o => !o)} style={{ width: 32, height: 32, borderRadius: 6, border: `1px solid ${T.border}`, background: T.cardBg, cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", position: "relative" }}>
        <Icon name="alert" size={15} color={items.length ? T.red : T.t3} />
        {items.length > 0 && <span style={{ position: "absolute", top: 5, right: 5, width: 7, height: 7, borderRadius: "50%", background: T.dangerGrad, animation: "pulseDot 1.6s infinite" }} />}
      </button>
      {open && (
        <div style={{ position: "absolute", right: 0, top: 38, width: 320, background: T.cardBg, border: `1px solid ${T.border}`, borderRadius: 10, boxShadow: "0 24px 60px rgba(0,0,0,.2)", zIndex: 60, overflow: "hidden" }}>
          <div style={{ padding: "11px 16px", borderBottom: `1px solid ${T.border}`, fontSize: 13, fontWeight: 600, color: T.t1 }}>Notifications</div>
          {items.length === 0 && <div style={{ padding: "14px 16px", fontSize: 13, color: T.t4 }}>All quiet.</div>}
          {items.slice(0, 7).map((n: any, i: number) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 9, padding: "0 16px", height: 42, borderTop: i > 0 ? `1px solid ${T.well}` : "none", fontSize: 12.5, color: T.t2 }}>
              <span style={{ width: 7, height: 7, borderRadius: "50%", background: n.tone === "red" ? T.dangerGrad : T.warnGrad, flex: "none" }} />
              <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{n.msg}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function ThemeToggle() {
  const store = useJobStore();
  const dark = store.theme === "dark";
  return (
    <button onClick={() => store.setTheme(dark ? "light" : "dark")} title="Theme"
      style={{ width: 32, height: 32, borderRadius: 6, border: `1px solid ${T.border}`, background: T.cardBg, cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", color: T.t3, fontSize: 13 }}>
      {dark ? "☀" : "☾"}
    </button>
  );
}

